    def __init__(self, job: Mapping[str, Any]):
        self.fields = list(job['fields'])
        self.names = {field['name']: index for index, field in enumerate(self.fields)}
        self.nf = len(self.names)
        self.slots = int(job['slots'])
        self.cell_count = self.slots * self.nf
        self.cell_domains: list[list[int]] = []
        for _slot in range(self.slots):
            for field in self.fields:
                self.cell_domains.append(list(field['domain']))
        sizes = [len(domain) for domain in self.cell_domains]
        total = 1
        for size in sizes:
            total *= size
        self.size = total
        flat = np.arange(total, dtype=np.int64)
        self.values: list[np.ndarray] = [None] * self.cell_count
        self.positions: list[np.ndarray] = [None] * self.cell_count
        self._prefix_cache: dict[tuple[str, str], np.ndarray] = {}
        self._spelling_cache: dict[str, list[str]] = {}
        self._continuation_cache: dict[tuple[str, int], np.ndarray] = {}
        self._exact_cache: dict[tuple[str, int], np.ndarray] = {}
        stride = 1
        for index in range(self.cell_count - 1, -1, -1):
            domain = np.asarray(self.cell_domains[index], dtype=np.int64)
            position = (flat // stride) % sizes[index]
            self.positions[index] = position
            self.values[index] = domain[position]
            stride *= sizes[index]

    def position(self, ref: Sequence[Any]) -> int:
        """Flat cell index of a ``[slot, field]`` reference."""
        return int(ref[0]) * self.nf + self.names[ref[1]]

    def field_domain(self, name: str) -> list[int]:
        """Declared domain of a field."""
        return list(self.fields[self.names[name]]['domain'])

    def spellings(self, name: str) -> list[str]:
        """Canonical decimal spellings of a field domain, by domain position."""
        cached = self._spelling_cache.get(name)
        if cached is None:
            cached = [str(value) for value in self.field_domain(name)]
            self._spelling_cache[name] = cached
        return cached

    def prefix_mask(self, name: str, prefix: str) -> np.ndarray:
        """Boolean mask of the domain positions whose spelling starts with ``prefix``."""
        key = (name, prefix)
        cached = self._prefix_cache.get(key)
        if cached is None:
            spellings = self.spellings(name)
            cached = np.fromiter(
                (spelling.startswith(prefix) for spelling in spellings),
                dtype=bool,
                count=len(spellings),
            )
            self._prefix_cache[key] = cached
        return cached

    def continuation(self, name: str, length: int) -> np.ndarray:
        """Character that follows a prefix of ``length`` characters, per domain position."""
        key = (name, length)
        cached = self._continuation_cache.get(key)
        if cached is None:
            spellings = self.spellings(name)
            cached = np.array(
                [spelling[length] if len(spelling) > length else '' for spelling in spellings],
                dtype='<U1',
            )
            self._continuation_cache[key] = cached
        return cached

    def exact_mask(self, name: str, length: int) -> np.ndarray:
        """Boolean mask of the domain positions whose spelling has ``length`` characters."""
        key = (name, length)
        cached = self._exact_cache.get(key)
        if cached is None:
            spellings = self.spellings(name)
            cached = np.fromiter(
                (len(spelling) == length for spelling in spellings),
                dtype=bool,
                count=len(spellings),
            )
            self._exact_cache[key] = cached
        return cached


def flatten_windows(job: Mapping[str, Any]) -> list[list[int]]:
    """Flatten every training window into slot-major, field-ordered cells."""
    rows: list[list[int]] = []
    for window in job['train']:
        flat: list[int] = []
        for row in window:
            flat.extend(int(value) for value in row)
        rows.append(flat)
    return rows


def column_vectors(rows: Sequence[Sequence[int]], columns: Sequence[str]) -> dict[str, np.ndarray]:
    """Dense columns for a list of flattened windows."""
    length = len(rows)
    vectors: dict[str, np.ndarray] = {}
    for index, name in enumerate(columns):
        vectors[name] = np.fromiter((row[index] for row in rows), dtype=np.int64, count=length)
    return vectors


def decode_queries(
    job: Mapping[str, Any],
    active_clauses: Sequence[Sequence[int]],
    universe: Universe,
    universe_true: Sequence[np.ndarray],
) -> list[dict]:
    """Answer every decoding query against the active theory."""
    theory = np.ones(universe.size, dtype=bool)
    for clause in active_clauses:
        satisfied = np.zeros(universe.size, dtype=bool)
        for predicate_id in clause:
            satisfied |= universe_true[predicate_id]
        theory &= satisfied

    answers: list[dict] = []
    for query in job.get('queries', []):
        mask = theory
        for binding in query.get('fixed') or []:
            cell = universe.position(binding['ref'])
            mask = mask & (universe.values[cell] == int(binding['value']))
        prefix = query.get('prefix', '')
        target_field = query['target'][1]
        target_cell = universe.position(query['target'])
        lookup = universe.prefix_mask(target_field, prefix)
        if lookup.any():
            mask = mask & lookup[universe.positions[target_cell]]
        else:
            mask = np.zeros(universe.size, dtype=bool)
